INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100001, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-1', 'single', '丁寧語（Teineigo）の特徴として正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100001, '相手（目上・お客様）の行動を高めて敬意を表す表現', 'Biểu đạt nâng cao hành động của đối phương (bề trên, khách hàng) để tỏ kính trọng', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100001, '自分（話し手・身内）の行動を低めて敬意を表す表現', 'Biểu đạt hạ thấp hành động của bản thân (người nói, người trong nhóm) để tỏ kính trọng', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100001, '誰の行動かに関係なく、文体を丁寧にする表現', 'Biểu đạt làm câu văn lịch sự bất kể ai hành động', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100001, '目上の人にだけ使う特別な語彙で、同僚には使わない表現', 'Từ vựng đặc biệt chỉ dùng với người bề trên, không dùng với đồng nghiệp', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100002, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-1', 'single', '「食べる」の丁寧語は何ですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100002, '召し上がる（めしあがる）', '召し上がる — ăn/uống (Sonkeigo)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100002, 'いただく', 'いただく — ăn/nhận (Kenjougo)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100002, '食べます', '食べます — ăn', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100002, 'お食べする', 'お食べする', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100003, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-1', 'single', '「きれいだ」の最も基本的な丁寧語は何ですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100003, 'きれいます', 'きれいます', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100003, 'きれいです', 'きれいです', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100003, 'お綺麗になる', 'お綺麗になる', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100003, 'きれいでございます', 'きれいでございます', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100004, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-1', 'single', '「お」と「ご」の使い分けについて正しい説明はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100004, 'どちらも意味は同じで、話し手の好みで自由に使い分けてよい', 'Cả hai giống nghĩa, tùy sở thích người nói mà dùng', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100004, '「お」は和語（日本固有語）につく、「ご」は漢語（漢字語）につく（原則）', '「お」đứng trước từ Nhật thuần (Wago), 「ご」đứng trước từ gốc Hán (Kango) — nguyên tắc chung', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100004, '「お」は謙譲語を作る接頭辞、「ご」は尊敬語を作る接頭辞である', '「お」là tiền tố tạo Kenjougo, 「ご」là tiền tố tạo Sonkeigo', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100004, '「ご」は書き言葉だけに使い、「お」は話し言葉だけに使う', '「ご」chỉ dùng trong văn viết, 「お」chỉ dùng trong khẩu ngữ', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100005, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-1', 'single', '次の中で「お」または「ご」の使い方が間違っているものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100005, 'お電話（おでんわ）', 'お電話 — điện thoại', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100005, 'ご名前（ごなまえ）', 'ご名前 — tên', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100005, 'ご住所（ごじゅうしょ）', 'ご住所 — địa chỉ', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100005, 'お時間（おじかん）', 'お時間 — thời gian', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100006, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-1', 'single', '「ない」の丁寧語は何ですか？（動詞の否定形）
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100006, '〜ないです（会話で自然に使われる否定形）', '〜ないです — dạng phủ định tự nhiên trong hội thoại', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100006, '〜ません（改まった場面で使う標準的な否定形）', '〜ません — dạng phủ định chuẩn dùng trong tình huống trang trọng', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100006, 'A と B の両方が丁寧語として正しい', 'Cả A và B đều là Teineigo phủ định đúng', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100006, '〜ないでしょう（否定の推量を表す形）', '〜ないでしょう — dạng phỏng đoán phủ định', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100007, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-1', 'single', 'ビジネス場面で「行く」の丁寧語の過去形と過去否定形として最も適切なものを選んでください。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100007, '行きました / 行きませんでした', '行きました / 行きませんでした', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100007, '行きました / 行かなかったです', '行きました / 行かなかったです', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100007, '行きました / 行きません', '行きました / 行きません', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100007, '行ったです / 行かないでした', '行ったです / 行かないでした', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100008, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-1', 'single', '次の「お」/「ご」がついた言葉のうち、Teineigo（丁寧語）として正しく使われているものはどれですか？
