INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100013, '否定：でございません / 過去：でございましたん', 'Phủ định: でございません / Quá khứ: でございましたん', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100013, '否定：ではないでございます / 過去：でありました', 'Phủ định: ではないでございます / Quá khứ: でありました', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100013, '否定：ではございません / 過去：でございましたでした', 'Phủ định: ではございません / Quá khứ: でございましたでした', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100014, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-2', 'single', '「〜でしょうか」の機能として正しいのはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100014, '推量（〜だろう）の丁寧語として、または丁寧な疑問文を作る', 'Teineigo của 〜だろう (phỏng đoán), hoặc tạo câu hỏi lịch sự', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100014, '過去に起こった出来事を推量する場合にだけ使うことができる', 'Chỉ dùng khi phỏng đoán sự việc đã xảy ra trong quá khứ', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100014, '「ですか」と全く同じ機能で、どんな場面でも置き換えが可能である', 'Hoàn toàn giống 「ですか」, có thể thay thế trong mọi tình huống', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100014, '相手に対する命令や強い依頼を表すために使う形である', 'Dạng dùng để biểu đạt mệnh lệnh hoặc yêu cầu mạnh với đối phương', FALSE, 4);
