INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100039, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-4', 'single', '次の受付の会話で最も自然なものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100039, '受付:「何のご用ですか」客:「田中部長に会いたい」受付:「少し待ってください」', 'Lễ tân: Có việc gì? / Khách: Muốn gặp Trưởng phòng Tanaka / Lễ tân: Chờ chút', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100039, '受付:「本日はどのようなご用件でいらっしゃいますか」客:「田中部長にご面会したいのですが」受付:「ただいまご連絡いたします。少々お待ちくださいませ」', 'Lễ tân: Hôm nay quý vị đến có việc gì ạ? / Khách: Tôi muốn gặp Trưởng phòng Tanaka ạ / Lễ tân: Tôi sẽ liên hệ ngay. Xin đợi chút ạ.', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100039, '受付:「何の用ですか」客:「田中部長に会いたいです」受付:「確認します」', 'Lễ tân: Có việc gì? / Khách: Tôi muốn gặp Trưởng phòng Tanaka / Lễ tân: Tôi sẽ xác nhận', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100039, '受付:「ご用件を承ります」客:「田中部長にお目にかかりたいのですが」受付:「田中部長はただいまいらっしゃいますので、少々お待ちください」', 'Lễ tân: Tôi xin nhận yêu cầu ạ / Khách: Tôi muốn được diện kiến Trưởng phòng Tanaka / Lễ tân: Trưởng phòng Tanaka hiện đang có mặt, xin đợi chút', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (81100040, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-4', 'single', '「お客様がご利用になったサービスについて、弊社の担当者よりご説明申し上げます」の敬語を正しく分析したものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100040, '全文が尊敬語で、お客様と担当者の両方の行動を高めている', 'Toàn câu là Sonkeigo, nâng cao hành động của cả khách lẫn nhân viên', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100040, '「ご利用になった」は尊敬語、「ご説明申し上げます」は謙譲語、文体は丁寧語', '「ご利用になった」= Sonkeigo | 「ご説明申し上げます」= Kenjougo | Văn phong = Teineigo', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100040, '「ご利用になった」は謙譲語、「申し上げます」は尊敬語で、役割が逆になっている', '「ご利用になった」là Kenjougo, 「申し上げます」là Sonkeigo — vai trò bị đảo ngược', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (81100040, '「弊社の担当者」の部分が敬語として誤っており、「弊社の担当者様」が正しい', 'Phần「弊社の担当者」sai kính ngữ, phải là「弊社の担当者様」', FALSE, 4);
