INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300001, 'いる・行く・来る', 'いる (ở) · 行く (đi) · 来る (đến)', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300001, 'いる・する・来る', 'いる (ở) · する (làm) · 来る (đến)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300001, '行く・言う・来る', '行く (đi) · 言う (nói) · 来る (đến)', FALSE, 3);
