INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300026, '田中部長が明日いらっしゃるとおっしゃっていました。', 'Trưởng phòng Tanaka nói rằng ngày mai ngài ấy sẽ đến.', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300026, '田中部長が明日参るとおっしゃっていました。', 'Trưởng phòng Tanaka nói rằng ngài ấy sẽ đến (参る = khiêm nhường ngữ — sai vì Tanaka là Soto)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300026, '田中部長が明日来ると申していました。', 'Trưởng phòng Tanaka đã nói rằng ngày mai sẽ đến.', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300026, '田中部長が明日いらっしゃると申していました。', 'Trưởng phòng Tanaka đã nói rằng ngài ấy sẽ đến.', FALSE, 4);
