INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300027, 'ご住所をお聞かせいただけますでしょうか？', 'Không biết quý vị có thể cho biết địa chỉ không ạ?', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300027, 'ご住所はいかがでしょうか？', 'Địa chỉ của ngài là thế nào ạ? (いかが)', FALSE, 3);
