INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (82300029, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-3', 'single', '「先生のおっしゃる通りです」— この文について正しい説明はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300029, '「おっしゃる通り」は「言った通り」の謙譲語表現である', '「おっしゃる通り」là Kenjougo của 言った通り', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300029, '「おっしゃる通り」は尊敬語で、同意を示す決まり文句である', '「おっしゃる通り」là Sonkeigo — thành ngữ thể hiện sự đồng ý', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300029, '「おっしゃる通り」は丁寧語で、誰に対しても使える表現である', '「おっしゃる通り」là Teineigo, dùng được với bất kỳ ai', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300029, 'この文は間違っている — 「おっしゃられる通り」が正しい', 'Câu này sai — phải là「おっしゃられる通り」', FALSE, 4);
