INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (82300033, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-4', 'single', 'あなたはA社員。B社のC部長（取引先）から「D社長（B社の社長）は来ますか？」と聞かれました。D社長がまだ来ていない場合、正しい答えは？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300033, 'D社長はまだおりません。', 'Chủ tịch D chưa đến. (おる)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300033, 'D社長はまだいらっしゃいません。', 'Chủ tịch D chưa đến ạ. (いらっしゃる)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300033, 'D社長はまだ参っておりません。', 'Chủ tịch D chưa đến ạ. (参る + おる)', FALSE, 3);
