INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (82300034, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-4', 'single', '次の文のうち、Sonkeigo（尊敬語）でお客様の行動を直接・明確に敬う表現として最も正しいものはどれですか？（全てお客様に対する発言）
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300034, 'お客様がお越しになりました際に、弊社の田中がご説明いたします。', 'Khi quý vị đến, Tanaka bên tôi sẽ giải thích.', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300034, 'お客様がいらっしゃいました際に、田中部長がご説明いたします。', 'Khi quý vị đến, Trưởng phòng Tanaka sẽ giải thích.', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300034, 'お客様がいらっしゃった際に、弊社の田中がご説明なさいます。', 'Khi quý vị đến, Tanaka bên tôi sẽ giải thích.', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300034, 'お越しいただいた際に、田中部長がご説明させていただきます。', 'Khi quý vị ghé đến, Trưởng phòng Tanaka xin được giải thích.', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (82300035, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_phan_loai', 'BJT-4', 'single', '「もし時間があれば、来てください」をお客様への丁寧な依頼にすると？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300035, 'もしよろしければ、お越しくださいませ。', 'Nếu quý vị thuận tiện, mời ngài ghé đến ạ.', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (82300035, 'もしよろしければ、いらっしゃってください。', 'Nếu thuận tiện, mời ngài đến ạ.', FALSE, 2);
