INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (83300026, '田中部長からご伝言がございます。', 'Trưởng phòng Tanaka có lời nhắn ạ. (ご伝言 + ございます)', FALSE, 1);
