INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84100031, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_juzu_doushi', 'BJT-4', 'single', '次の文の誤りを指摘してください。「お客様、こちらの資料をあげますので、お持ちください。」
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100031, '「お持ちください」が間違い', '「お持ちください」sai', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100031, '「あげます」が間違い', '「あげます」sai', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100031, '「こちらの資料」が間違い', '「こちらの資料」sai', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100031, '「お客様」の呼びかけが間違い', 'Cách xưng hô「お客様」sai', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84100032, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_juzu_doushi', 'BJT-4', 'single', '次の文の誤りを指摘してください。「昨日、社長が私に賞状をくれました。とてもうれしかったです。」
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100032, '「とてもうれしかったです」が間違い、敬語にすべき', '「とてもうれしかったです」sai, phải dùng kính ngữ', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100032, '「くれました」が間違い、「くださいました」にすべき', '「くれました」sai, phải là「くださいました」', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100032, '「賞状を」が間違い、「表彰状を」にすべき', '「賞状を」sai, phải là「表彰状を」', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100032, '「昨日」が間違い、「先日」にすべきで日付も不要', '「昨日」sai, phải là「先日」và không cần ghi ngày', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84100033, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_juzu_doushi', 'BJT-4', 'single', '「ご支援を賜り、厚く御礼申し上げます」の「賜り（たまわり）」の意味と使用場面として正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100033, '「あげる」の謙譲語で、日常会話でよく使われる', 'Là khiêm nhường ngữ của「あげる」, hay dùng trong hội thoại hàng ngày', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100033, '「もらう・いただく」の上位の謙譲語で、公式文書で使う', 'Là khiêm nhường ngữ cao hơn「もらう・いただく」, dùng trong văn bản chính thức', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100033, '「くれる・くださる」と同じ意味で、話し言葉でも使える', 'Cùng nghĩa với「くれる・くださる」, dùng được cả trong khẩu ngữ', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100033, '「やる」の丁寧語で、目下の人に使う', 'Là Teineigo của「やる」, dùng với người bề dưới', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84100034, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_juzu_doushi', 'BJT-4', 'single', '「させていただく」の使い方として最も不自然なものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100034, 'では、資料をご説明させていただきます。', 'Vậy thì tôi xin phép giải thích tài liệu ạ.', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100034, '明日から育児休暇を取得させていただきます。', 'Từ mai tôi xin phép nghỉ chế độ chăm con.', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100034, '田中と申させていただきます。', 'Tôi xin phép được tự xưng là Tanaka.', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100034, '本日は休業させていただきます。', 'Hôm nay chúng tôi xin phép nghỉ kinh doanh.', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84100035, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_juzu_doushi', 'BJT-4', 'single', '「私は弟に英語を教えてあげた。／弟は私に英語を教えてもらった。／弟が私に英語を教えてくれた。」3つの文の中で意味が【異なる】ものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100035, '①だけが異なる', 'Chỉ ① khác nghĩa', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100035, '①と③が同じ意味、②だけが異なる', '① và ③ cùng nghĩa, chỉ ② khác', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100035, '①と②は同じ意味、③だけが異なる', '① và ② cùng nghĩa, chỉ ③ khác', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100035, '3つとも異なる意味', 'Cả ba đều khác nghĩa', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84100036, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_juzu_doushi', 'BJT-4', 'single', '取引先から不当な要求をされ、断る場面。最も適切な断り方はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100036, 'それはできません。', 'Điều đó không làm được.', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100036, 'それはいたしかねます。', 'Điều đó chúng tôi e rằng khó thực hiện được ạ.', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100036, 'それはしてあげられません。', 'Điều đó tôi không thể làm giúp được.', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100036, 'それはさしあげられません。', 'Điều đó tôi không thể kính tặng được.', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84100037, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_juzu_doushi', 'BJT-4', 'single', '次の電話での会話で、誤りを含む発言はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100037, '（ア）のみ', 'Chỉ (ア)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100037, '（イ）のみ', 'Chỉ (イ)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100037, '（ウ）のみ', 'Chỉ (ウ)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100037, '（ア）（イ）（ウ）すべて正しい', 'Cả (ア)(イ)(ウ) đều đúng', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84100038, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_juzu_doushi', 'BJT-4', 'single', '以下の場面に最も適した全体的な表現の流れはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100038, '製品を説明してあげて、カタログをあげて帰ってもらった。', 'Tôi đã giải thích sản phẩm giúp, cho catalog rồi để khách về. (してあげて／あげた)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100038, '製品をご説明いたし、カタログをお持ちいただいた。', 'Tôi đã giải thích sản phẩm ạ, và đã nhờ khách mang catalog. (いたし／お持ちいただいた)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100038, '製品をご説明させていただき、カタログをお持ち帰りになった。', 'Tôi xin phép giải thích sản phẩm ạ, và quý khách đã mang catalog về. (させていただき／お持ち帰りになった)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100038, '製品を説明してさしあげ、カタログをいただいて見送った。', 'Tôi đã giải thích sản phẩm giúp, nhận catalog rồi tiễn khách. (してさしあげ／いただいた)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84100039, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_juzu_doushi', 'BJT-4', 'single', '社外向けの正式な挨拶文として最も格調の高い表現はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100039, '皆様のご支援をもらい、ありがとうございます。', 'Cảm ơn vì đã nhận được sự hỗ trợ của mọi người. (もらう)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100039, '皆様のご支援をいただき、ありがとうございます。', 'Cảm ơn vì đã nhận được sự hỗ trợ của quý vị ạ. (いただく)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100039, '皆様のご支援を賜り、厚く御礼申し上げます。', 'Xin chân thành cảm tạ ân tình hỗ trợ mà quý vị đã ban cho. (賜る + 御礼申し上げる)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100039, '皆様のご支援をくれて、誠にありがとうございます。', 'Thành thật cảm ơn vì mọi người đã cho sự hỗ trợ. (くれる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84100040, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_juzu_doushi', 'BJT-4', 'single', '次のビジネスシーンで、授受動詞・敬語を含む全体的に最も適切な表現はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100040, '田中から頼まれたんですが、会議の日程を変えてもらえますか。', 'Tôi được Tanaka nhờ, anh/chị đổi lịch họp cho tôi được không?', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100040, '田中より申し付かりまして、誠に勝手ながら、会議の日程をご変更いただけますでしょうか。', 'Tôi được Tanaka giao nhiệm vụ, thật mạo muội, quý vị có thể đổi lịch họp được không ạ?', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100040, '田中部長に頼まれましたので、会議の日程を変更してください。', 'Vì được Trưởng phòng Tanaka nhờ nên xin hãy đổi lịch họp.', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84100040, '田中部長が日程を変更してあげると言っています。ご都合はいかがですか。', 'Trưởng phòng Tanaka nói sẽ đổi lịch giúp. Quý vị có tiện không?', FALSE, 4);
