INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84200006, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_juzu_doushi', NULL, 'single', '「弊社のIT部門が貴社のシステムを検討いたしましたところ、非常に高く評価しております」という表現について、誰が誰を評価していますか。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200006, '貴社が弊社を高く評価している', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200006, 'システムはあまり良くなかったが、社交辞令として褒めている', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200006, '山本さんが貴社から受け取った高い評価に感謝している', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200006, '弊社のIT部門が貴社のシステムを高く評価した、という事実', NULL, TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84200007, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_juzu_doushi', NULL, 'single', '「ご相談させていただきたく」と「サポートをいただきたい」という二つの授受動詞の使い方で、誰が誰に何をしているか、最も正確な説明はどれですか。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200007, '弊社が貴社のシステムについて判断を与え、貴社がそれに従っている', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200007, '貴社が弊社に相談を強要して、技術サポートを命じている', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200007, '弊社が貴社に相談することについて許可を求め、技術サポートを受けたいと言っている', NULL, TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200007, '貴社が弊社に相談内容を提供し、弊社がそれを評価している', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84200008, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_juzu_doushi', NULL, 'single', '「トレーニングを実施していただける時間をお作りいただけますでしょうか」という長い表現は、実質的にはどのような依頼を表していますか。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200008, '貴社の時間が足りないので、弊社が時間をあげるという申し出', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200008, 'トレーニングの日程を決めてほしいという依頼', NULL, TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200008, '弊社が貴社に時間を与える提案', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200008, 'トレーニングは必要ないという拒絶', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84200009, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_juzu_doushi', NULL, 'single', 'A社様が「この修正案で進めていただきたい」と言った時、誰が誰に何をするということを求めていますか。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200009, 'A社が青山さんの会社に対して、修正案で進めることを依頼・許可している', NULL, TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200009, 'A社が青山さんの会社に、修正案で進めることを許可している', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200009, '青山さんの会社がA社に修正案の実行を強要している', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200009, 'A社がA社自身で修正案を進めることを宣言している', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (84200010, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_juzu_doushi', NULL, 'single', '「弊社の企画部門がプロジェクト案を修正させていただきました」という表現で、「させていただく」が使われている理由として、最も適切なのはどれですか。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (84200010, '修正権が自社にあるので、自分たちが修正したことを主張するため', NULL, FALSE, 1);
