INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100001, '「内」は自分より目上の人、「外」は自分より目下の人', '「内」là người bề trên mình, 「外」là người bề dưới mình', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100001, '「内」は自分が属するグループ、「外」はそのグループ外の人', '「内」là nhóm mình thuộc về, 「外」là người ngoài nhóm đó', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100001, '「内」は会社の上司や先輩、「外」は会社の部下や後輩である', '「内」là cấp trên/tiền bối, 「外」là cấp dưới/hậu bối trong công ty', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100001, '「内」は親しい友人や知人、「外」はまだ知らない人である', '「内」là bạn bè/người quen thân, 「外」là người chưa quen', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100002, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-1', 'single', 'あなたが会社の社員（B社勤務）のとき、「内（uchi）」に含まれる人をすべて選んでください。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100002, '自分・同僚・直属の上司・自社の社長', 'Bản thân · đồng nghiệp · cấp trên trực tiếp · giám đốc công ty mình', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100002, '自分・自社の同僚・取引先のお客様', 'Bản thân · đồng nghiệp công ty mình · khách hàng đối tác', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100002, '自分・友人・他社の社員', 'Bản thân · bạn bè · nhân viên công ty khác', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100002, '自分だけ', 'Chỉ mình bản thân', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100003, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-1', 'single', '内外のルールに従うと、外の人（お客様）に対して話す時、内の人（自社の上司）についてはどのように話すべきですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100003, '上司なので尊敬語を使って敬意を示す', 'Vì là cấp trên nên dùng tôn kính ngữ để tỏ lòng kính trọng', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100003, '上司への敬意をお客様にも示すため、最高の敬語を使う', 'Để thể hiện lòng kính trọng với cấp trên cả trước khách, dùng kính ngữ cao nhất', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100003, '内の人として扱い、敬語を外し、謙譲語または普通語で話す', 'Coi là người trong nhóm, bỏ tôn kính ngữ, nói bằng khiêm nhường ngữ hoặc dạng thường', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100003, '上司かどうかに関係なく、丁寧語だけ使えばよい', 'Bất kể là cấp trên hay không, chỉ cần dùng lịch sự ngữ là đủ', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100004, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-1', 'single', '電話で取引先のA社の鈴木様と話している時、次のうち「外（soto）」にあたる人は誰ですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100004, 'あなた自身', 'Chính bản thân bạn', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100004, 'あなたの同僚', 'Đồng nghiệp của bạn', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100004, 'あなたの直属の部長', 'Trưởng phòng trực tiếp của bạn', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100004, 'A社の鈴木様', 'Ông Suzuki công ty A', TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100005, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-1', 'single', '取引先への電話で、自社の山田部長が不在の場合、正しい言い方はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100005, '山田部長はただいまいらっしゃいません。', 'Trưởng phòng Yamada hiện không có mặt ạ. (いらっしゃる)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100005, '山田部長はただいま外出されております。', 'Trưởng phòng Yamada hiện đang đi ra ngoài ạ. (される + おる)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100005, '山田はただいま外出しております。', 'Yamada hiện đang đi ra ngoài ạ. (おる, bỏ 部長)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100005, '山田部長様はただいま不在でございます。', 'Ngài Trưởng phòng Yamada hiện đang vắng mặt ạ. (部長様)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100006, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-1', 'single', '田中さんは自社（B社）の社員です。同じ田中さんについて話す時、相手によって敬語の使い方が変わります。どれが正しいですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100006, 'どんな相手でも「田中さんがいらっしゃいます」と言う', 'Với bất kỳ ai cũng nói「田中さんがいらっしゃいます」', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100006, '社内には「田中さんがいます」、社外には「田中はおります」', 'Nội bộ:「田中さんがいます」, đối tác:「田中はおります」', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100006, '社内でも社外でも同じように「田中はいます」と言えばよい', 'Cả trong lẫn ngoài đều nói giống nhau là「田中はいます」', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100006, '取引先に対しては「田中部長がいらっしゃいます」と言う', 'Với đối tác thì nói「田中部長がいらっしゃいます」', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100007, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-1', 'single', 'お客様（社外の人）に「うちの父が先日お世話になりました」と言う時、「うちの父」についての敬語の使い方として正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100007, '「お父様」と言って敬意を示す', 'Gọi là「お父様」để tỏ lòng kính trọng', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100007, '「パパ」と親しみを込めて言う', 'Gọi thân mật là「パパ」', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100007, '「父上（ちちうえ）」という古風な言い方をする', 'Gọi bằng cách nói cổ「父上（ちちうえ）」', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100007, '「父（ちち）」と言い、敬語をつけない', 'Gọi là「父（ちち）」, không thêm kính ngữ', TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100008, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-1', 'single', '次のうち、「内外関係」についての正しい説明はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100008, '内外関係は固定していて、どんな状況でも変わらない', 'Quan hệ Uchi/Soto cố định, không thay đổi trong bất kỳ tình huống nào', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100008, 'お客様は親しくなれば「内」の人になれる', 'Khách hàng nếu thân thiết thì có thể trở thành người「内」', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100008, '社長はどんな場面でも常に「外」の人として扱われる', 'Giám đốc trong mọi tình huống luôn được xử lý như người「外」', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100008, '内外関係は話す相手と状況によって変わる相対的なものである', 'Quan hệ Uchi/Soto là tương đối, thay đổi theo người nghe và hoàn cảnh', TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100009, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-1', 'single', '外（お客様）と話す時の基本ルールとして正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100009, 'お客様の行動→尊敬語、自社の行動→謙譲語', 'Hành động của khách → tôn kính ngữ, hành động của công ty mình → khiêm nhường ngữ', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100009, 'お客様の行動→謙譲語、自社の行動→尊敬語', 'Hành động của khách → khiêm nhường ngữ, hành động của công ty mình → tôn kính ngữ', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100009, 'すべての人に尊敬語を使う', 'Dùng tôn kính ngữ với tất cả mọi người', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100009, 'すべての人に謙譲語を使う', 'Dùng khiêm nhường ngữ với tất cả mọi người', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100010, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-1', 'single', '取引先との電話で「うちの社長の田中がおっしゃっていました」という表現の問題点はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100010, '「社長」という役職名を出すこと自体が失礼にあたる', 'Việc nêu chức danh「社長」tự nó đã là thất lễ', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100010, '「田中」と名字だけで呼ぶのが取引先に対して失礼', 'Gọi trống tên「田中」là thất lễ với đối tác', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100010, '「おっしゃっていました」は内の人に使う尊敬語なので間違い', '「おっしゃっていました」là tôn kính ngữ dùng cho người trong nhóm nên sai', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100010, '「うちの」という言い方が社外に対して失礼にあたる', 'Cách nói「うちの」là thất lễ với người ngoài', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100011, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-2', 'single', '社外から電話がかかってきた。「田中部長はいらっしゃいますか」と聞かれた。田中部長は席にいる。正しい答えはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100011, 'はい、田中部長はいらっしゃいます。少々お待ちください。', 'Vâng, Trưởng phòng Tanaka đang có mặt. Xin đợi chút. (いらっしゃる)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100011, 'はい、田中はおります。少々お待ちください。', 'Vâng, Tanaka đang có mặt ạ. Xin đợi chút ạ. (おる, bỏ 部長)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100011, 'はい、田中部長がおります。お待ちください。', 'Vâng, Trưởng phòng Tanaka đang có mặt. Xin đợi. (おる, giữ 部長)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100011, 'はい、田中様はおります。少々お待ちください。', 'Vâng, ngài Tanaka đang có mặt ạ. Xin đợi chút ạ. (田中様)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100012, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-2', 'single', '取引先への折り返し電話を約束する文として正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100012, '田中部長からご連絡させていただきます。', 'Trưởng phòng Tanaka xin phép liên hệ ạ. (部長 + させていただく)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100012, '田中からご連絡いたします。', 'Tanaka sẽ liên hệ với quý vị ạ. (いたす, bỏ 部長)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100012, '田中部長がお電話くださいます。', 'Trưởng phòng Tanaka sẽ gọi điện ạ. (くださる)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100012, '田中様よりご連絡申し上げます。', 'Ngài Tanaka sẽ liên hệ ạ. (様 + 申し上げる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100013, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-2', 'single', '社外へのメールで上司（鈴木部長）が確認済みであることを伝える。正しい表現はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100013, '鈴木部長がご確認されました。', 'Trưởng phòng Suzuki đã xác nhận ạ. (ご確認される)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100013, '鈴木部長がご確認なさいました。', 'Trưởng phòng Suzuki đã xác nhận ạ. (ご確認なさる)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100013, '鈴木が確認いたしました。', 'Suzuki đã xác nhận ạ. (いたす, bỏ 部長)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100013, '鈴木部長様がご確認くださいました。', 'Ngài Trưởng phòng Suzuki đã xác nhận cho ạ. (部長様 + くださる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100014, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-2', 'single', 'お客様（A社の山田様）に自社の部長を紹介する場面。正しい紹介の仕方はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100014, 'こちらは弊社の田中部長でいらっしゃいます。', 'Đây là Trưởng phòng Tanaka của công ty chúng tôi ạ. (でいらっしゃる)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100014, 'こちらは弊社の部長の田中でございます。', 'Đây là Tanaka, trưởng phòng của công ty chúng tôi ạ. (でございます)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100014, 'こちらは田中部長様です。どうぞよろしくお願いいたします。', 'Đây là ngài Trưởng phòng Tanaka ạ. Rất mong được hợp tác. (部長様)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100014, 'こちらが弊社の田中部長がいらっしゃいます。', 'Đây là Trưởng phòng Tanaka của công ty chúng tôi ạ. (が + いらっしゃる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100015, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-2', 'single', '社外の人に自社のことを話す時、「自社」の呼び方として正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100015, '御社（おんしゃ）— 話し言葉で使う', '御社（おんしゃ）— dùng trong khẩu ngữ', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100015, '貴社（きしゃ）— 書き言葉で使う', '貴社（きしゃ）— dùng trong văn viết', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100015, '弊社（へいしゃ）または当社（とうしゃ）', '弊社（へいしゃ）hoặc 当社（とうしゃ）', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100015, 'うちの会社様 — 社外向けの言い方', 'うちの会社様 — cách gọi hướng ra ngoài', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100016, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-2', 'single', 'お客様に「担当の山田が後ほどご説明します」と言う時、正しい言い方はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100016, '担当の山田さんがご説明されます。', 'Anh Yamada phụ trách sẽ giải thích ạ. (さん + ご説明される)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100016, '担当の山田がご説明いたします。', 'Yamada phụ trách sẽ giải thích ạ. (いたす, bỏ さん)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100016, '担当の山田様がご説明なさいます。', 'Ngài Yamada phụ trách sẽ giải thích ạ. (様 + なさる)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100016, '担当の山田がご説明してくれます。', 'Yamada phụ trách sẽ giải thích cho ạ. (してくれる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100017, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-2', 'single', 'お客様（B社の鈴木様）からの伝言を上司（田中部長）に伝える場面。正しい言い方はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100017, 'B社の鈴木が申しておりました。', 'Suzuki công ty B đã nói ạ. (申す)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100017, 'B社の鈴木様が申し上げておりました。', 'Ngài Suzuki công ty B đã thưa ạ. (様 + 申し上げる)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100017, 'B社の鈴木さんが言っていました。', 'Anh Suzuki công ty B đã nói. (さん + 言う)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100017, 'B社の鈴木様がおっしゃっていました。', 'Ngài Suzuki công ty B đã nói ạ. (様 + おっしゃる)', TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100018, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-2', 'single', '受付でお客様を迎える場面で、担当者を呼びに行く時の正しい表現はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100018, '担当の山田さんをお呼びします。少々お待ちください。', 'Tôi sẽ gọi anh Yamada phụ trách. Xin đợi chút. (さん)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100018, '担当の山田部長様をお呼びいたします。少々お待ちくださいませ。', 'Tôi xin gọi ngài Trưởng phòng Yamada phụ trách. Xin đợi chút ạ. (部長様)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100018, '担当の山田をお呼びいたします。少々お待ちくださいませ。', 'Tôi xin gọi Yamada phụ trách. Xin đợi chút ạ. (bỏ さん, くださいませ)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100018, '山田がいらっしゃいますので、少々お待ちください。', 'Yamada sẽ đến nên xin đợi chút. (いらっしゃる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100019, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-2', 'single', '「田中部長が帰社した」ことを、異なる相手に伝える時、それぞれの正しい言い方を選んでください。①社内の同僚に：②社外の取引先に：
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100019, '①田中部長がお戻りになりました。②田中がただいま戻りました。', '① Trưởng phòng Tanaka đã quay về ạ. (お戻りになる) ② Tanaka vừa quay về ạ. (戻りました)', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100019, '①田中部長が戻りました。②田中はただいま戻りました。', '① Trưởng phòng Tanaka đã quay về. (戻りました, không kính ngữ) ② Tanaka vừa quay về ạ. (戻りました)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100019, '①田中部長がお戻りになりました。②田中はただいまお戻りになりました。', '① Trưởng phòng Tanaka đã quay về ạ. (お戻りになる) ② Trưởng phòng Tanaka đã quay về ạ. (お戻りになる)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100019, '①田中が戻りました。②田中部長がお戻りになりました。', '① Tanaka đã quay về. (戻りました) ② Trưởng phòng Tanaka đã quay về ạ. (お戻りになる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100020, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-2', 'single', '社外向けのメールで、相手の会社に言及する時の正しい呼び方はどれですか？（書き言葉）
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100020, '御社（おんしゃ）', '御社（おんしゃ）', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100020, '貴社（きしゃ）', '貴社（きしゃ）', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100020, '弊社（へいしゃ）', '弊社（へいしゃ）', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100020, '当社（とうしゃ）', '当社（とうしゃ）', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100021, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-3', 'single', 'A社（取引先）とB社（自社）とC社（別の取引先）の3社が絡む場面。B社社員（話し手）がA社の山田様にC社について話す場合、C社はA社とB社それぞれにとって何ですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100021, 'C社はB社にとって外（soto）だが、A社との関係は判断する必要がないため考えなくてよい', 'C là Soto với B, nhưng quan hệ với A thì không cần phán đoán nên bỏ qua', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100021, 'C社はA社にとって「内（uchi）」であり、B社にとってのみ「外（soto）」として扱われる', 'C là「内（uchi）」với A, và chỉ là「外（soto）」với B', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100021, 'C社はA社にもB社にも「外（soto）」であり、A社に話す時もC社は「外」として扱う', 'C là「外（soto）」với cả A lẫn B; khi nói với A vẫn xử lý C như「外」', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100021, 'C社は取引関係にあるため、A社にとってもB社にとっても「内（uchi）」として扱われる', 'Vì có quan hệ giao dịch nên C là「内（uchi）」với cả A lẫn B', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100022, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-3', 'single', 'あなた（B社）がA社に訪問した場合、A社の山田部長についての言及方法として正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100022, '山田はいらっしゃいますか。（A社の受付に）', 'Yamada có ở đó không ạ? (bỏ chức danh, いらっしゃる)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100022, '山田様がいますか。（A社の受付に）', 'Ngài Yamada có ở đó không? (様 + いる)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100022, '山田部長はおりますか。（A社の受付に）', 'Trưởng phòng Yamada có ở đó không? (おる)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100022, '山田部長はいらっしゃいますか。（A社の受付に）', 'Trưởng phòng Yamada có ở đó không ạ? (giữ chức danh, いらっしゃる)', TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100023, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-3', 'single', '上司（田中部長）の意向を、取引先のA社の鈴木様に伝える場面。正しい言い方はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100023, '田中部長がぜひご参加したいとおっしゃっていました。', 'Trưởng phòng Tanaka nói rằng rất muốn tham gia ạ. (部長 + おっしゃる)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100023, '弊社の田中が、ぜひ参加したいと申しております。', 'Tanaka bên chúng tôi nói rằng rất muốn tham gia ạ. (弊社の + 申す)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100023, '田中部長様が参加されるとおっしゃっていました。', 'Ngài Trưởng phòng Tanaka nói rằng sẽ tham gia ạ. (部長様 + される + おっしゃる)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100023, '田中がぜひ参加したいと申し上げていました。', 'Tanaka nói rằng rất muốn tham gia ạ. (申し上げる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100024, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-3', 'single', '取引先の山田様が「田中部長は本当に優秀でいらっしゃいますね」とおっしゃった。適切な返答はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100024, 'そうですね、田中部長はとても優秀でいらっしゃいます。', 'Vâng, Trưởng phòng Tanaka rất xuất sắc ạ. (でいらっしゃる)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100024, 'ありがとうございます。田中はおかげさまで頑張っております。', 'Cảm ơn ngài. Nhờ ơn quý vị mà Tanaka đang cố gắng ạ. (おる)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100024, 'そうですよ、うちの田中部長様は本当にすごいんです。', 'Đúng vậy, ngài Trưởng phòng Tanaka của chúng tôi thật sự giỏi lắm.', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100024, 'ありがとうございます。田中部長のおかげです。', 'Cảm ơn ngài. Là nhờ Trưởng phòng Tanaka ạ. (giữ 部長)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100025, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-3', 'single', '今月入社したばかりの新人社員（山田くん）について、取引先に言及する場合の正しい表現はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100025, '新人の山田がご対応いたします。', 'Yamada nhân viên mới sẽ tiếp nhận ạ. (いたす, bỏ さん)', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100025, '新人の山田さんがご対応されます。', 'Anh Yamada nhân viên mới sẽ tiếp nhận ạ. (さん + される)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100025, '新人の山田くん様がご対応いたします。', 'Ngài Yamada nhân viên mới sẽ tiếp nhận ạ. (くん様)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100025, '新人の山田部下がご対応させていただきます。', 'Cấp dưới Yamada nhân viên mới xin phép tiếp nhận ạ. (部下 + させていただく)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100026, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-3', 'single', 'A社とB社（自社）の合同プロジェクトについて、C社（別の取引先）にメールで報告する場面。A社の田中様について言及する正しい方法は？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100026, 'A社の田中が申しておりました。', 'Tanaka công ty A đã nói ạ. (申す)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100026, 'A社の田中部長が申し上げておりました。', 'Trưởng phòng Tanaka công ty A đã thưa ạ. (部長 + 申し上げる)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100026, 'A社の田中部長様がご発言なさいました。', 'Ngài Trưởng phòng Tanaka công ty A đã phát biểu ạ. (部長様 + なさる)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100026, 'A社の田中様がおっしゃっておりました。', 'Ngài Tanaka công ty A đã nói ạ. (様 + おっしゃる)', TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100027, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-3', 'single', '会議室で、自社の部長（田中部長）と取引先のお客様（鈴木様）が同席している。あなたが二人に同時に話す場合の言い方として正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100027, '田中部長と鈴木様の両名に対してすべて尊敬語を使えばよい', 'Dùng tôn kính ngữ cho cả Trưởng phòng Tanaka lẫn ông Suzuki', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100027, '田中部長にも鈴木様にもすべて謙譲語を使えばよい', 'Dùng khiêm nhường ngữ cho cả Trưởng phòng Tanaka lẫn ông Suzuki', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100027, '鈴木様（外）には尊敬語、田中部長（内）には謙譲語・平語を使う', 'Với ông Suzuki (ngoài) dùng tôn kính ngữ; với Trưởng phòng Tanaka (trong) dùng khiêm nhường ngữ hoặc dạng thường', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100027, '同席の場では敬語を使わず、普通体で話しても問題ない', 'Khi ngồi chung thì không cần kính ngữ, nói dạng thường cũng không sao', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100028, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-3', 'single', '自社の担当者（山田）がお客様（B社の鈴木様）に失礼をしてしまった。あなたが代わりに謝罪する場面で正しい表現はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100028, '山田さんが失礼をいたしまして、大変申し訳ございません。', 'Anh Yamada đã thất lễ, chúng tôi vô cùng xin lỗi ạ. (さん + いたす)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100028, '山田が失礼を申し上げまして、大変申し訳ございません。', 'Yamada đã nói điều thất lễ, chúng tôi vô cùng xin lỗi ạ. (申し上げる)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100028, '山田が大変失礼いたしました。誠に申し訳ございません。', 'Yamada đã vô cùng thất lễ ạ. Chúng tôi thành thật xin lỗi ạ. (いたす, bỏ さん)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100028, '山田くんがご失礼されまして、申し訳ございません。', 'Cậu Yamada đã thất lễ, xin lỗi ạ. (くん + ご失礼される)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100029, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-3', 'single', 'あなたはA株式会社の社員です。A株式会社はBグループの傘下にあります。Bグループの別の子会社C株式会社の社員と取引先の前で話す場合、C社の社員はあなたにとって「内」ですか「外」ですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100029, '同じグループ企業なので、どんな場面でも常に「内（uchi）」である', 'Vì cùng tập đoàn nên trong mọi tình huống luôn là「内（uchi）」', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100029, '法人格が別なので、どんな場面でも常に「外（soto）」である', 'Vì tư cách pháp nhân khác nhau nên luôn là「外（soto）」', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100029, '状況によるが、一般的には「外（soto）」として扱うのが安全', 'Tùy tình huống, nhưng nói chung xử lý như「外（soto）」là an toàn', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100029, '派遣・出向と同じく、内外のルール自体が適用されない', 'Giống phái cử/biệt phái, bản thân quy tắc Uchi/Soto không áp dụng', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100030, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-3', 'single', '社外イベントでの挨拶スピーチで「弊社の会長が〜とおっしゃっておりました」という表現を使った。この表現の問題点は何ですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100030, '「弊社」という謙称を公の場で使うのが間違い', 'Dùng khiêm xưng「弊社」ở nơi công cộng là sai', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100030, '「会長」という役職名をそのまま出すのが失礼', 'Nêu thẳng chức danh「会長」là thất lễ', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100030, '「おっしゃっておりました」は内の人に使う尊敬語なので間違い', '「おっしゃっておりました」là tôn kính ngữ dùng cho người trong nhóm nên sai', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100030, 'スピーチという公の場なので、表現は自由でよい', 'Vì là bài phát biểu công khai nên diễn đạt thế nào cũng được', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100031, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-4', 'single', '次の電話応対の会話で、内外のルール違反を含む発言はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100031, '（ア）のみ', 'Chỉ (ア)', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100031, '（イ）のみ', 'Chỉ (イ)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100031, '（ウ）のみ', 'Chỉ (ウ)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100031, 'すべて正しい', 'Tất cả đều đúng', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100032, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-4', 'single', '社外向けのメールで誤りがあるものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100032, '弊社の山田が確認いたしました。', 'Yamada bên chúng tôi đã xác nhận ạ. (いたす)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100032, '弊社の鈴木部長がご確認なさいました。', 'Trưởng phòng Suzuki bên chúng tôi đã xác nhận ạ. (部長 + なさる)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100032, '弊社の田中よりご連絡いたします。', 'Tanaka bên chúng tôi sẽ liên hệ ạ. (いたす)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100032, '弊社の佐藤が参ります。', 'Sato bên chúng tôi sẽ đến ạ. (参る)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100033, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-4', 'single', '「弊社の佐藤部長様がおっしゃっておられました」という文には誤りがいくつありますか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100033, '0個（すべて正しい）', '0 lỗi (tất cả đều đúng)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100033, '1個', '1 lỗi', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100033, '2個', '2 lỗi', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100033, '3個', '3 lỗi', TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100034, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-4', 'single', '社外向けの正式なビジネスレターの書き出しとして最も適切なものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100034, '貴社ますますご清栄のこととお慶び申し上げます。', 'Kính chúc quý công ty ngày càng thịnh vượng ạ. (貴社 + お慶び申し上げる)', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100034, '御社ますますご清栄のこととお慶び申し上げます。', 'Kính chúc quý công ty ngày càng thịnh vượng ạ. (御社 + お慶び申し上げる)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100034, '弊社ますますご清栄のこととお慶び申し上げます。', 'Kính chúc công ty chúng tôi ngày càng thịnh vượng ạ. (弊社)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100034, '貴社ますますご清栄のこととお喜びいたします。', 'Kính chúc quý công ty ngày càng thịnh vượng ạ. (貴社 + お喜びいたす)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100035, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-4', 'single', '次の受付での会話で、内外のルール通り正しく使われているものの組み合わせはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100035, '（ア）（イ）（ウ）', '(ア)(イ)(ウ)', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100035, '（ア）（ウ）（エ）', '(ア)(ウ)(エ)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100035, '（イ）（ウ）（エ）', '(イ)(ウ)(エ)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100035, '（ア）（イ）（ウ）（エ）すべて正しい', 'Cả (ア)(イ)(ウ)(エ) đều đúng', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100036, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-4', 'single', 'かつて自社に勤めていた山田さん（現在は退職してA社に勤務）が来社した。山田さんはUchi（内）ですか、Soto（外）ですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100036, '元社員なので今でも「内（uchi）」', 'Vì là cựu nhân viên nên hiện nay vẫn là「内（uchi）」', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100036, '上司に確認する必要があり、自分で判断できない', 'Cần hỏi cấp trên, bản thân không thể tự phán đoán', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100036, '親しい間柄なので「内」でも「外」でもどちらでもよい', 'Vì thân thiết nên coi là「内」hay「外」đều được', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100036, '現在はA社の社員なので「外（soto）」として扱う', 'Vì hiện đang là nhân viên công ty A nên xử lý như「外（soto）」', TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100037, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-4', 'single', 'A社から弊社に派遣されている派遣社員の山田さんについて、取引先のB社に言及する場合、山田さんはUchi（内）ですか、Soto（外）ですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100037, 'A社に籍があるため、どんな場面でも常に「外（soto）」である', 'Vì có hộ tịch ở công ty A nên trong mọi tình huống luôn là「外（soto）」', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100037, '弊社で日々働いているので、常に「内（uchi）」として扱ってよい', 'Vì làm việc hằng ngày ở công ty mình nên luôn xử lý như「内（uchi）」', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100037, '状況により異なる（社内での行動は内、所属はA社）', 'Tùy tình huống (hành động trong công ty là Uchi, nơi công tác là A)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100037, '派遣社員には内外のルールは適用されない', 'Với nhân viên phái cử thì không áp dụng quy tắc Uchi/Soto', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100038, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-4', 'single', 'B社（自社）の山田部長がA社に電話して、A社の鈴木部長と話した内容を、後でC社の佐藤様に報告する場面。各人についての正しい言及方法は？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100038, '山田部長が→弊社の山田が、鈴木部長→A社の鈴木様が、佐藤様→C社の佐藤が', '山田部長→弊社の山田が, 鈴木部長→A社の鈴木様が, 佐藤様→C社の佐藤が', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100038, '弊社の山田が（謙）、A社の鈴木様が（尊）、C社の佐藤様に（尊）', '弊社の山田が (Uchi→khiêm), A社の鈴木様が (Soto→tôn kính), C社の佐藤様に (Soto→tôn kính)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100038, '弊社の山田部長様が（尊）、A社の鈴木が（謙）、C社の佐藤様に（尊）', '弊社の山田部長様が (tôn kính), A社の鈴木が (khiêm), C社の佐藤様に (tôn kính)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100038, '山田部長が（尊）、鈴木様が（謙）、佐藤が（平）と使い分ける', '山田部長が (tôn kính), 鈴木様が (khiêm), 佐藤が (dạng thường)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100039, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-4', 'single', '次のメール文で誤っている箇所を特定してください。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100039, '「貴社ますますご清栄」の部分が間違い', 'Phần「貴社ますますご清栄」sai', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100039, '「田中部長様」と「おっしゃっていた」の2か所が間違い', '「田中部長様」và「おっしゃっていた」— 2 chỗ sai', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100039, '「ご来社いただき」の部分が間違い', 'Phần「ご来社いただき」sai', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100039, '「どうぞよろしくお願いいたします」が間違い', '「どうぞよろしくお願いいたします」sai', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85100040, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_uchi_soto', 'BJT-4', 'single', '次の状況を説明する最も適切な文章はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100040, '田中社長が来週お伺いになりたいとおっしゃっています。', 'Trưởng phòng Tanaka nói muốn đến thăm tuần sau ạ. (部長 + お伺いになる + おっしゃる)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100040, '弊社の田中が来週お伺いしたいと申しております。', 'Tanaka bên chúng tôi nói muốn đến thăm tuần sau ạ. (弊社の + お伺いする + 申す)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100040, '田中社長様が来週いらっしゃいたいとおっしゃっています。', 'Ngài Trưởng phòng Tanaka nói muốn đến tuần sau ạ. (社長様 + いらっしゃる + おっしゃる)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85100040, '弊社の田中社長が来週参りたいと申し上げています。', 'Chủ tịch Tanaka bên chúng tôi nói muốn đến tuần sau ạ. (giữ 社長 + 参る + 申し上げる)', FALSE, 4);
