INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85200007, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_uchi_soto', NULL, 'single', '「田中も、貴社とのパートナーシップを大切にしておりますので、どうぞよろしく（　）いたします。」の（　）に入る正しい表現は？
