INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (85200008, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_uchi_soto', NULL, 'single', '下線部の表現について、敬語の使い方として正しい評価はどれですか。「田中も、貴社とのパートナーシップを大切にしておりますので」
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85200008, '''おります'' là sai vì tôn kính quá mức với Uchi', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85200008, 'Phải đổi ''おります'' thành ''いらっしゃいます''', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85200008, '''大切にしています'' (không khiêm nhường) sẽ đúng hơn khi nói với Soto', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85200008, 'Không có lỗi — ''おります'' là khiêm nhường ngữ (謙譲語) dùng đúng cho Uchi', NULL, TRUE, 4);
