INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85200009, '弊社：鈴木部長・山田さん、相手方：佐藤さん・山本さん', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (85200009, '弊社：鈴木様・山田課長、相手方：佐藤さん・山本さん', NULL, FALSE, 3);
