INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100004, '受身（bị động）— 部長が誰かに入らせられた', 'Bị động — Trưởng phòng bị ai đó bắt vào', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100004, '尊敬（tôn kính）— 部長が入るという行為を丁寧に表す', 'Tôn kính — diễn đạt lịch sự hành động vào phòng của Trưởng phòng', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100004, '可能（có thể）— 部長が会議室に入ることができた', 'Khả năng — Trưởng phòng đã có thể vào phòng họp', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100004, '自発（tự phát）— 自然と会議室に入ってしまった', 'Tự phát — tự nhiên mà vào phòng họp mất rồi', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (86100005, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_ukemi_shieki', 'BJT-1', 'single', '「先生は生徒（　）作文（　）書かせた。」正しい助詞の組み合わせはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100005, 'を／が', 'を／が', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100005, 'に／を', 'に／を', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100005, 'が／を', 'が／を', FALSE, 3);
