INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (86100006, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_ukemi_shieki', 'BJT-1', 'single', '「母は子どもを/に泣かせた。」自動詞（泣く）の使役文で、「を」と「に」どちらが正しいですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100006, '「を」のみ正しく、「に」は自動詞使役では使えない', 'Chỉ「を」đúng, 「に」không dùng được với sai khiến tự động từ', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100006, '「に」のみ正しく、「を」は自動詞使役では使えない', 'Chỉ「に」đúng, 「を」không dùng được với sai khiến tự động từ', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100006, '「を」は強制・放置、「に」は許可・誘導の意味で両方使える', '「を」mang nghĩa ép buộc/thả mặc, 「に」mang nghĩa cho phép/hướng dẫn — cả hai đều dùng được', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100006, 'どちらも間違いで、自動詞は使役形にできない', 'Cả hai đều sai, tự động từ không thể chia sai khiến', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (86100007, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_ukemi_shieki', 'BJT-1', 'single', '「私は上司に3時間も残業させられた。」この文の意味として正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100007, '私が上司に残業するよう命令した', 'Tôi đã ra lệnh cho sếp làm thêm giờ', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100007, '私が自分の意志で残業した（自発的に）', 'Tôi tự nguyện làm thêm giờ (theo ý chí bản thân)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100007, '私は上司から残業するよう強制された（不本意）', 'Tôi bị sếp ép buộc phải làm thêm giờ (bất đắc dĩ)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100007, '私が上司のために自分から残業した', 'Tôi tự mình làm thêm giờ vì sếp', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (86100008, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_ukemi_shieki', 'BJT-1', 'single', '動詞「書く」（グループ1）の、①受動形、②使役形、③使役受動形を正しく示したものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100008, '①書かれる ②書かせる ③書かせられる', '①書かれる ②書かせる ③書かせられる', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100008, '①書かれる ②書けさせる ③書けさせられる', '①書かれる ②書けさせる ③書けさせられる', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100008, '①書かれる ②書かせる ③書かせされる', '①書かれる ②書かせる ③書かせされる', FALSE, 3);
