INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (86100009, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_ukemi_shieki', 'BJT-1', 'single', '「先生に褒められた」と「先生に褒めてもらった」の違いとして正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100009, '①は受身で客観的な表現、②は感謝・恩恵の気持ちを表す', '① là bị động, diễn đạt khách quan; ② thể hiện lòng biết ơn, cảm nhận ân huệ', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100009, '①②ともに全く同じ意味で、違いは一切ない', 'Cả ① và ② hoàn toàn cùng nghĩa, không có bất kỳ khác biệt nào', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100009, '①は自然に起きたこと、②は自分から頼んで起きたこと', '① là việc xảy ra tự nhiên, ② là việc xảy ra do mình chủ động nhờ', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100009, '①は先生が悪い人、②は先生が良い人', '① nghĩa là thầy xấu tính, ② nghĩa là thầy tốt bụng', FALSE, 4);
