INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100013, '「を」は、社長が社員に帰る許可を与えた', '「を」nghĩa là giám đốc cho phép nhân viên về', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100013, '「を」は使えない、「に」でなければならない', 'Không dùng được「を」, bắt buộc phải là「に」', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100013, '「を」と「に」は意味も語感も全く同じである', '「を」và「に」hoàn toàn giống nhau cả về nghĩa lẫn sắc thái', FALSE, 4);
