INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100016, '新入社員が自ら進んで掃除に取り組んでいる', 'Nhân viên mới tự nguyện, chủ động bắt tay vào dọn dẹp', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100016, '新入社員が掃除するよう誰かに命じられている（不本意）', 'Nhân viên mới bị ai đó ra lệnh phải dọn dẹp (bất đắc dĩ)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100016, '新入社員が掃除することを許可されている', 'Nhân viên mới được cho phép dọn dẹp', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100016, '新入社員が掃除を他の誰かにさせている', 'Nhân viên mới đang sai người khác dọn dẹp', FALSE, 4);
