INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (86100020, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_ukemi_shieki', 'BJT-2', 'single', '次の2文の違いを正しく説明したものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100020, '①②ともに全く同じ意味で、違いは一切ない', 'Cả ① và ② hoàn toàn cùng nghĩa, không có khác biệt', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100020, '①は自分の意志・謙虚な申し出、②は不本意・強制', '① là ý chí bản thân, đề nghị khiêm tốn; ② là bất đắc dĩ, bị ép buộc', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100020, '①は相手への命令、②は相手からの許可を表す', '① là mệnh lệnh với đối phương, ② là sự cho phép từ đối phương', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100020, '①は過去の出来事、②は現在の状態を表す', '① diễn tả sự việc quá khứ, ② diễn tả trạng thái hiện tại', FALSE, 4);
