INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (86100039, '①山田さんは田中部長に評価書を書かれた。②山田さんは田中部長によって評価書を書かせた。', '①山田さんは田中部長に評価書を書かれた。②山田さんは田中部長によって評価書を書かせた。', FALSE, 3);
