INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200001, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '「資料を参考にさせていただき」の表現として最も適切な説明は？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200001, '課長が私に資料を参考にするよう指示した', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200001, '資料は私に参考にされてしまった', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200001, '私が資料を参考にしたことを課長に許可をもらった', NULL, TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200001, '課長が資料を参考にするのを手伝った', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200002, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '「ご送付いただき」と「を送ってもらい」を比較した場合、正しい説明は？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200002, '意味は同じだが、いただくはより敬語で丁寧な言い方である', NULL, TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200002, 'いただくは課長が主体で、もらうは私が主体で受け取る', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200002, 'いただくは過去完了で、もらうは現在進行である', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200002, '両方とも同じで、文法的に区別する必要がない', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200003, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '下線部「ご報告させていただきたく存じます」は「報告させられたく存じます」に置き換えられますか。その理由は？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200003, 'できる。両方とも同じ意味である', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200003, 'できない。なぜなら「させられる」は不本意な強制を表すが、ここは「許可を求める」意味だから', NULL, TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200003, 'できない。なぜなら「させられる」は過去形で、「させていただく」は未来形だから', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200003, 'できる。「させられる」はより丁寧な表現だから', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200004, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', 'メール全体の送信者の態度として最も正確なものは？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200004, '課長に不満があり、資料の品質に疑問を持っている', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200004, '課長の指示が複雑で、理解するのに困っている', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200004, '課長に感謝し、資料を活用できたことを報告し、さらに指導を希望している', NULL, TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200004, '会議に参加したくないので、別の提案を考えている', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200005, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '営業が「特別に対応させていただきたい」と言った最も適切な理由は？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200005, '顧客が営業に対応するよう強制しようとしている', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200005, '過去に同じ対応をさせられたことがある', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200005, '営業は顧客の要求に全く応じたくない', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200005, '営業が特別な対応をしたいことを顧客に提案し、許可を求めている', NULL, TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200006, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '「金額の値引きをしていただけますか」と「金額の値引きをさせていただけますか」の意味の違いは？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200006, '前者は顧客が営業に値引きしてほしいと依頼する；後者は営業が値引きしたいことを顧客に許可を求める', NULL, TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200006, '意味は全く同じで、使い分ける必要がない', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200006, '前者は敬語で、後者は普通語である', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200006, '前者は過去形で、後者は未来形である', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200007, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '「金額については、10%の値引きをさせていただく」の表現から、営業の気持ちとして最も正確なものは？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200007, '値引きの提案をする権利と責任を持ち、顧客に敬意を表しながら提供する準備がある', NULL, TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200007, '10%の値引きが最高だと顧客に強制している', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200007, '顧客を支配したいという意図が強い', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200007, '顧客は強制的に値引きを受けなければならない', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200008, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '全体の通話記録から見ると、顧客と営業の関係において最も正確な説明は？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200008, '顧客は営業に不満を持ち、別の会社に変える準備をしている', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200008, '営業は顧客の要求に応じるために、最善の努力をしていて、顧客も合意している', NULL, TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200008, '顧客は営業を完全に支配している', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200008, '営業は顧客に逆らい、値引きを拒否している', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200009, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '「外部のコンサルタントに相談させていただき」の表現に見られる、報告者の態度は？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200009, 'コンサルタントに強制的に相談させた', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200009, '報告者はコンサルタントを支配している', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200009, 'コンサルタントは必ず相談に応じなければならない', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200009, '自分たちが外部の専門家に相談することを決定し、その判断を管理者に報告している', NULL, TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200010, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '「改善案に基づいて、チーム内で検討させていただく」の表現において、最も適切な説明は？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200010, 'チームに検討することを強制している', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200010, 'チームが改善案を検討することを決定し、それを管理者に報告・許可を求めている', NULL, TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200010, '管理者が検討するよう指示した', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200010, '検討は既に完了している', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200011, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '「テスト期間については、管理者の許可を得て、2週間延長させていただきたく存じます」は「2週間延長してもらいたく存じます」に置き換えられますか。その理由は？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200011, 'できない。「してもらう」はより敬語だから', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200011, 'できる。両方とも同じ意味である', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200011, 'できない。「させていただく」は報告者（チーム）が延長を実行する主体であり、「してもらう」は管理者が延長を実行する意味だから', NULL, TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200011, 'できる。後者のほうが自然である', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200012, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '「若手メンバーには…再設計作業を担当させ、実務を通じて学ばせております」と「次回の定例会議で議題として取り上げていただけますでしょうか」の二つの表現の違いとして、最も正確な説明はどれですか。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200012, '両方とも謙譲語で、報告者自身の行動を述べている', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200012, '前者も後者も使役形で、どちらも部下に指示を出している', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200012, '前者は受動形で若手が被害を受けていること、後者は使役形である', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200012, '前者は使役形で報告者が部下に作業を行わせること、後者は「〜ていただく」で報告者が上司に行動をお願いすることを表す', NULL, TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200013, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '田中が「誰か担当していただける人はいますか」と言い、佐藤が「私に担当させていただけますでしょうか」と応じた。この二つの表現の使い分けとして最も正確な説明はどれですか。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200013, '田中は「〜ていただく」で他の人が担当してくれることを求め、佐藤は「〜させていただく」で自分自身が担当することの許可を求めている', NULL, TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200013, '田中も佐藤も「させていただく」を使っており、どちらも自分が担当したいと言っている', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200013, '田中は佐藤に担当を強制しており、佐藤はそれを断っている', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200013, 'どちらも受動形で、担当を押し付けられた状況を表している', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200014, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '佐藤が「私に担当させていただけますでしょうか」と言ったのに対して、田中が「では、佐藤さんにプロジェクト管理をお任せしたいと思います」と答えた理由として正確なものは？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200014, '田中は佐藤にプロジェクト管理を任せたくないから', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200014, '田中にはこの決定を下す権限がないから', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200014, '佐藤が依頼を断ったから', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200014, '田中に決定権はあるが、謙譲語「お任せする」を用いて、敬意を込めて丁寧に任せているから', NULL, TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200015, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '「重大な決定については、私に相談していただくことを希望します」という田中の発言の意図として、最も適切なものは？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200015, '佐藤は相談せずに独自に決定してよいという意味である', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200015, '田中が佐藤に完全に従うという意味である', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200015, '重大な決定については、佐藤が田中に相談することを期待している', NULL, TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200015, '相談するかどうかは任意で、佐藤が自由に決めてよいという意味である', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200016, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', '鈴木の「管理者から明確な指示をしていただきたいです」に対して、田中が「明確な権限設定をさせていただくことを約束」と答えた意味として最も正確なものは？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200016, '田中は権限設定をしたくないという意味である', NULL, FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200016, '田中自身が権限設定を行う主体であり、それを実行することを、出席者への敬意を込めて約束している', NULL, TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200016, '権限設定は鈴木の責任であるという意味である', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200016, '田中が鈴木に完全に従うという意味である', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200017, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', 'FAXで「貴社の新製品を弊社のマーケティングキャンペーンで紹介していただきたく」と書かれた理由として最も適切なものは？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200017, 'ABC Marketing は貴社に紹介することを要求し、許可を求めている', NULL, TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200017, 'ABC Marketing が自社の製品を紹介する', NULL, FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200017, '貴社は紹介することを強制させられている', NULL, FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87200017, '貴社は紹介を拒否する権利がない', NULL, FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87200018, NULL, TRUE, FALSE, 'reading', 'keigo_dokkai_keigo_tong_hop', NULL, 'single', 'FAXの「弊社の営業チームに、製品説明の機会を設けていただけますか」と、返信メールの「弊社が御社の営業チームに詳しく説明させていただくことは可能です」の関係として正確な説明は？
