INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300001, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-1', 'single', '友人が私の荷物を持ってくれた場面。次の2文の違いを正しく説明したものはどれですか？
