INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300001, '①は友人が主語、②は私が主語になる', '① lấy bạn làm chủ ngữ, ② lấy tôi làm chủ ngữ', FALSE, 2);
