INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300016, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-2', 'single', '「先日ご来社いただきありがとうございました」と「先日ご来社くださりありがとうございました」の違いはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300016, '「いただき」が間違いで、「くださり」だけが正しい', '「いただき」sai, chỉ「くださり」đúng', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300016, '①は謙譲の視点、②は尊敬の視点で両方正しい', '① là góc nhìn khiêm nhường (mình nhận), ② là góc nhìn tôn kính (đối phương làm) — cả hai đều đúng', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300016, '「くださり」が間違いで、「いただき」だけが正しい', '「くださり」sai, chỉ「いただき」đúng', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300016, '①②は全く同じ意味で、視点の違いもない', 'Cả hai cùng nghĩa, cũng không khác về góc nhìn', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300017, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-2', 'single', '取引先への電話で「確認の上、折り返しご連絡（　）。」最も適切なのはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300017, 'させられます', 'させられます (bị ép liên lạc)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300017, 'させてもらいます', 'させてもらいます (được phép liên lạc)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300017, 'させていただきます', 'させていただきます (xin phép liên lạc)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300017, 'してもらいます', 'してもらいます (nhờ đối phương liên lạc)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300018, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-2', 'single', '部下が困っている時、上司として適切な対応の表現はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300018, '私が書類を作成してあげます。', 'Tôi sẽ lập tài liệu giúp cậu. (してあげる)', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300018, '書類を作成させます。', 'Tôi sẽ bắt (cậu) lập tài liệu. (させる)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300018, '一緒に書類を作成させてもらいます。', 'Tôi xin phép cùng lập tài liệu. (させてもらう)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300018, '書類を作成させていただきます。', 'Tôi xin phép lập tài liệu ạ. (させていただく)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300019, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-2', 'single', '社外の先輩に研修で指導してもらった後のお礼メールで、最も適切な表現はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300019, '研修でご指導されまして、ありがとうございました。', 'Cảm ơn vì đã được hướng dẫn trong khóa đào tạo ạ. (ご指導される)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300019, '研修でご指導くださいまして、誠にありがとうございました。', 'Thành thật cảm ơn vì đã hướng dẫn tôi trong khóa đào tạo ạ. (ご指導くださる)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300019, '研修でご指導させていただきまして、ありがとうございました。', 'Cảm ơn vì tôi xin phép hướng dẫn trong khóa đào tạo ạ. (させていただく)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300019, '研修でご指導させられまして、ありがとうございました。', 'Cảm ơn vì bị ép hướng dẫn trong khóa đào tạo ạ. (させられる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300020, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-2', 'single', '「部長が私に企画書を書く機会を与えてくれた」という状況。この状況を表す3つの表現の中で正しくないものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300020, '部長が私に企画書を書かせてくださった。', 'Trưởng phòng đã cho phép tôi viết đề xuất. (書かせてくださる)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300020, '私は部長に企画書を書かせていただいた。', 'Tôi đã được trưởng phòng cho phép viết đề xuất. (書かせていただく)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300020, '私は部長に企画書を書かせられた。', 'Tôi bị trưởng phòng bắt viết đề xuất. (書かせられる)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300020, '部長が私に企画書を書く機会をくださった。', 'Trưởng phòng đã cho tôi cơ hội viết đề xuất. (機会をくださる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300021, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-3', 'single', '「上司が私の代わりに会議に出てくれた」という状況を最もビジネスらしく言い換えると？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300021, '上司に会議に出られた。', 'Tôi bị sếp dự họp. (出られる)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300021, '上司に会議に出させた。', 'Tôi bắt sếp dự họp. (出させる)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300021, '上司に会議にご出席いただいた。', 'Tôi đã được sếp dự họp giúp ạ. (ご出席いただく)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300021, '上司が会議に出させてもらった。', 'Sếp đã xin phép được dự họp. (出させてもらう)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300022, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-3', 'single', '子どもが「自分でやりたい！」と言っている場面。親の対応として「してあげる」と「させてあげる」はどう違いますか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300022, '①②ともに子どもが行動することになる', 'Cả ① và ② đều là đứa trẻ thực hiện hành động', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300022, '①②ともに親が行動することになる', 'Cả ① và ② đều là phụ huynh thực hiện', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300022, '①は子どもが行動し、②は親が行動する', '① là đứa trẻ thực hiện, ② là phụ huynh thực hiện', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300022, '①は親が行動、②は子どもが行動できるよう許可', '① phụ huynh thực hiện (thay trẻ), ② phụ huynh cho phép để trẻ tự làm', TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300023, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-3', 'single', '「いただく」が2つの異なる意味で使われています。次の文のいただくの意味の違いを説明してください。
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300023, '①②ともに物（お菓子など）を受け取る意味である', 'Cả ① và ② đều mang nghĩa nhận vật (bánh kẹo v.v.)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300023, '①は行為を受け、②は物を受け取る意味である', '① là nhận hành động, ② là nhận vật', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300023, '①は物を受け取る本動詞、②は行為を受ける補助動詞', '① là động từ chính (nhận VẬT), ② là động từ bổ trợ (nhận HÀNH ĐỘNG)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300023, '①②ともに〜してもらうの謙譲語として働く', 'Cả ① và ② đều là khiêm nhường ngữ của 〜してもらう', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300024, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-3', 'single', '「自分がプレゼンをしたい」という意思を伝える3つの表現を正しく使い分けたものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300024, 'させてくれ ＜ させてもらいたい ＜ させていただけますでしょうか', 'させてくれ ＜ させてもらいたい ＜ させていただけますでしょうか', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300024, 'させていただけますでしょうか ＜ させてもらいたい ＜ させてくれ', 'させていただけますでしょうか ＜ させてもらいたい ＜ させてくれ', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300024, 'させてもらいたい ＜ させてくれ ＜ させていただけますでしょうか', 'させてもらいたい ＜ させてくれ ＜ させていただけますでしょうか', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300024, 'すべて同じ丁寧さ', 'Cả ba cùng mức lịch sự', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300025, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-3', 'single', '「部下に報告書を早く仕上げてほしい」という意味で、上司として最も適切な言い方はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300025, '報告書を早く仕上げてほしい。', 'Tôi muốn cậu hoàn thành báo cáo sớm. (てほしい)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300025, '報告書を早く仕上げてくれないか。', 'Cậu hoàn thành báo cáo sớm giúp tôi nhé? (てくれないか)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300025, '報告書を早く仕上げてもらいたい。', 'Tôi muốn được cậu hoàn thành báo cáo sớm. (てもらいたい)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300025, '報告書を早く仕上げさせていただきたい。', 'Tôi xin phép được hoàn thành báo cáo sớm. (させていただきたい)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300026, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-3', 'single', '「会議に参加したい」という意思を異なる相手に伝える場合、正しい使い分けはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300026, '①させてもらえる？②させてもらえますか？③させていただけますでしょうか？', '①させてもらえる？②させてもらえますか？③させていただけますでしょうか？', TRUE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300026, '①させていただけますでしょうか？②させてもらえる？③させてもらえますか？', '①させていただけますでしょうか？②させてもらえる？③させてもらえますか？', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300026, '①②③ともに「させていただけますでしょうか」', 'Cả ①②③ đều dùng「させていただけますでしょうか」', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300026, '①②③ともに「させてもらえる？」', 'Cả ①②③ đều dùng「させてもらえる？」', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300027, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-3', 'single', '企画書についての上司のフィードバックを受けた場面。どちらの表現が感謝の気持ちを表しますか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300027, '①のみ感謝を含む', 'Chỉ ① hàm chứa lòng biết ơn', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300027, '②のみ感謝を含む', 'Chỉ ② hàm chứa lòng biết ơn', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300027, '①②ともに感謝を含む', 'Cả ① và ② đều hàm chứa lòng biết ơn', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300027, '①②ともに感謝を含まない', 'Cả ① và ② đều không hàm chứa lòng biết ơn', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300028, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-3', 'single', '次の2つの依頼文で「誰が行動するか」が異なります。正しい説明はどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300028, '①②ともに相手がコピーすることになる', 'Cả ① và ② đều là đối phương photo', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300028, '①②ともに自分がコピーすることになる', 'Cả ① và ② đều là mình photo', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300028, '①は相手がコピーし、②は自分がコピーする', '① là đối phương photo, ② là mình photo', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300028, '①は自分がコピーする許可、②は相手への依頼', '① là mình photo (xin phép), ② là nhờ đối phương photo', TRUE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300029, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-3', 'single', '「田中さんが私に日本語を教えた」という状況を表現した次の4文のうち、出来事として実際に起きたかどうかが異なるものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300029, '田中さんが私に日本語を教えてくれた。', 'Tanaka đã dạy tôi tiếng Nhật. (てくれた)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300029, '私は田中さんに日本語を教えてもらった。', 'Tôi đã được Tanaka dạy tiếng Nhật. (てもらった)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300029, '私は田中さんに日本語を教えてもらいたかった。', 'Tôi đã muốn được Tanaka dạy tiếng Nhật. (てもらいたかった)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300029, '私は田中さんに日本語を教えられた。', 'Tôi đã bị Tanaka dạy tiếng Nhật. (られた)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300030, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-3', 'single', '「この本を読ませてもらいました」と「この本をもらいました」の意味の違いとして正しいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300030, '①は本の所有権が移り、②は一時的な許可である', '① quyền sở hữu sách đã chuyển giao, ② chỉ được phép tạm thời', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300030, '①②ともに一時的な許可を得ただけである', 'Cả ① và ② đều chỉ là được phép tạm thời', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300030, '①②ともに本の所有権が移ったことになる', 'Cả ① và ② đều là quyền sở hữu sách đã chuyển giao', FALSE, 3);
