INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300034, 'コピーをもらって、会議の資料を確認させていただきました。', 'Nhận bản photo rồi tôi đã kiểm tra tài liệu họp. (もらって + させていただく)', FALSE, 2);
