INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300035, '部長に仕事を手伝われた。', 'Tôi bị trưởng phòng giúp việc. (手伝われた)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300035, '部長に仕事を手伝ってもらった。', 'Tôi đã được trưởng phòng giúp việc. (てもらった)', FALSE, 3);
