INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300036, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-4', 'single', '次のビジネス場面での発言で、論理的・文法的に最もおかしいものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300036, '弊社の製品をお試しいただけますでしょうか。', 'Quý vị có thể dùng thử sản phẩm của chúng tôi không ạ? (お試しいただく)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300036, '資料をご確認させていただきたいのですが。', 'Tôi xin phép được kiểm tra tài liệu ạ. (ご確認させていただく)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300036, 'お客様に弊社の商品を選ばせていただきました。', 'Tôi đã xin phép chọn sản phẩm của công ty tôi cho khách ạ. (お客様に〜させていただく)', TRUE, 3);
