INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300037, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-4', 'single', '上司から「君のプレゼンは良かった」と言われた場面。次の表現の中でビジネス敬語として最も適切なものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300037, '部長にプレゼンが良かったと言われました。', 'Tôi được trưởng phòng nói rằng bài thuyết trình tốt. (言われた)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300037, '部長にプレゼンが良かったとおっしゃっていただきました。', 'Tôi được trưởng phòng nói rằng bài thuyết trình tốt ạ. (おっしゃっていただく)', FALSE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300037, '部長からプレゼンが良かったとのお言葉をいただきました。', 'Tôi đã nhận được lời khen từ trưởng phòng rằng bài thuyết trình tốt ạ. (お言葉をいただく)', TRUE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300037, '部長にプレゼンが良かったと言わせました。', 'Tôi bắt trưởng phòng nói rằng bài thuyết trình tốt. (言わせる)', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300038, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-4', 'single', '以下の6つの表現を、「誰が行動するか」「感情・ニュアンス」で正しく分類したものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300038, '①③⑤は話し手が行動、②④⑥は相手が行動する', '①③⑤ là người nói hành động, ②④⑥ là đối phương hành động', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300038, '①④⑤⑥は話し手が行動、②③は相手が話し手のために行動', '①④⑤⑥ là người nói hành động; ②③ là đối phương hành động vì người nói', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300038, '①〜⑥すべて話し手が行動することを表す', 'Tất cả ①〜⑥ đều là người nói hành động', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300038, '①〜⑥すべて相手が行動することを表す', 'Tất cả ①〜⑥ đều là đối phương hành động', FALSE, 4);
INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300039, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-4', 'single', '次のビジネス会話の（ア）〜（ウ）に最も適切な表現を選んでください。
