INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300039, 'ア:させてあげる／イ:させられます／ウ:させていただきたい', 'ア:させてあげる／イ:させられます／ウ:させていただきたい', FALSE, 2);
