INSERT INTO questions (id, user_id, is_system, is_khoa_cu, question_type, content_type, level, selection_type, question, passage, passage_translation, general_explanation, skill_category, base_difficulty, tenant_id, is_active, is_deleted, created_at, created_by) VALUES (87300040, NULL, TRUE, FALSE, 'chon_dap_an', 'keigo_baitap_keigo_tong_hop', 'BJT-4', 'single', '次のビジネスメールで、授受動詞・受動形・使役形の使い方が最も適切なものはどれですか？
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300040, '先日は弊社の会議にご出席させていただき、誠にありがとうございました。今後とも弊社をご支援させてください。', 'Cảm ơn vì tôi xin phép dự họp của công ty chúng tôi ạ. Xin cho tôi được hỗ trợ quý vị. (ご出席させていただく)', FALSE, 1);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300040, '先日は弊社の会議にご出席いただき、誠にありがとうございました。今後とも弊社へのご支援をよろしくお願い申し上げます。', 'Thành thật cảm ơn quý vị đã dự họp của chúng tôi ạ. Kính mong quý vị tiếp tục hỗ trợ. (ご出席いただく)', TRUE, 2);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300040, '先日は弊社の会議にご出席されていただき、誠にありがとうございました。今後とも弊社をご支援させていただければ幸いです。', 'Cảm ơn vì đã dự họp ạ. Rất vui nếu tôi được hỗ trợ quý vị. (ご出席されていただく)', FALSE, 3);
INSERT INTO questions_answers (question_id, sentence, sentence_translation, is_correct, "order") VALUES (87300040, '先日は弊社の会議にご出席してもらい、ありがとうございました。今後とも支援させてください。', 'Cảm ơn vì đã dự họp. Xin cho tôi được hỗ trợ. (ご出席してもらう)', FALSE, 4);
